import sys

def can_reduce_to_single_letter(s, c):
    # If the string length is 1 and it matches the target letter, return True
    if len(s) == 1 and s == c:
        return True

    # If the string length is odd and greater than 1, check if the target letter is in the string
    if len(s) > 1 and len(s) % 2 == 1:
        return c in s

    return False

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        s = data[index]
        c = data[index + 1]
        index += 2

        if can_reduce_to_single_letter(s, c):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
